#!/usr/bin/env python3
"""Check the observed accepted-load/annulled-younger-parcel regression."""
import argparse,hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def rows(p):return[json.loads(x)for x in Path(p).read_text().splitlines()]
def main():
 p=argparse.ArgumentParser(__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);negative=ROOT/'build/rocket-packet-head-diagnostic-v2';control=ROOT/'build/rocket-packet-head-diagnostic-v1';positive=ROOT/'build/rocket-packet-replay-fixed-scalar-prefix-v1'
 fields=dict((k,int(v))for k,v in re.findall(r'(expected_pc|expected_raw|expected_bytes|observed_pc|observed_raw|tick)=(\d+)',(negative/'stderr').read_text()));assert set(fields)=={'expected_pc','expected_raw','expected_bytes','observed_pc','observed_raw','tick'}
 assert (negative/'features.jsonl').read_bytes()==(control/'features.jsonl').read_bytes();assert(negative/'packets.jsonl').read_bytes()==(control/'packets.jsonl').read_bytes();assert(negative/'stderr').read_bytes()==(control/'stderr').read_bytes()
 badtrace=rows(negative/'async.jsonl');fallback=[x for x in badtrace if x['event']=='load-coherence-fallback-debug'and x['hart']==2 and x['restart_pc']==fields['expected_pc']and x['cycle']<fields['tick']][-1];old=[x for x in rows(negative/'packets.jsonl')if x['event']=='instruction_accept'and x['cycle']<=fields['tick']and x['pc']in(fallback['load_pc'],fallback['restart_pc'])];load=[x for x in old if x['pc']==fallback['load_pc']][-1];younger=[x for x in old if x['pc']==fallback['restart_pc']][-1];assert load['cycle']<younger['cycle']<fallback['cycle']<fields['tick'];assert younger['raw']==fields['expected_raw']and younger['bytes']==fields['expected_bytes']
 fixed=rows(positive/'packets.jsonl');redirect=[x for x in fixed if x['event']=='redirect'and x['reason']=='load-coherence-replay'and x['cycle']==fallback['cycle']];assert len(redirect)==1
 reaccepted=[x for x in fixed if x['event']=='instruction_accept'and x['pc']==fallback['restart_pc']and x['cycle']>=fallback['cycle']];assert reaccepted and reaccepted[0]['raw']==fields['expected_raw']and reaccepted[0]['bytes']==fields['expected_bytes'];assert reaccepted[0]['cycle']==fields['tick']
 assert sum(x['event']=='instruction_accept'and x['pc']==fallback['load_pc']and load['cycle']<=x['cycle']<=reaccepted[0]['cycle']for x in fixed)==1
 run=json.loads((positive/'run.json').read_text());summary=json.loads((positive/'summary.json').read_text());assert run['exit_status']==0 and run['intentional_instruction_cap']==1000000 and not run['normal_guest_exit_verified'];assert summary['cycles']>fields['tick']and sum(summary['retired_instructions'])>900000;assert not(positive/'stderr').read_bytes()
 evidence={'failure':fields,'actual_coherence_fallback':fallback,'load_parcel':load,'annulled_younger_parcel':younger,'actual_repair_redirect':redirect[0],'correct_refetch':reaccepted[0],'negative_diagnostic_streams_identical':True,'positive_accepted_load_repeated':False,'positive_final_model_cycle':summary['cycles'],'positive_retired':summary['retired_instructions']};(out/'witness.json').write_text(json.dumps(evidence,indent=2)+'\n')
 inputs=[Path(__file__).resolve(),*[d/n for d in[negative,control,positive]for n in['run.json','stdout','stderr','features.jsonl','packets.jsonl']],negative/'async.jsonl',positive/'async.jsonl',positive/'summary.json',ROOT/'pipeline/riscv-isa-sim-empirical-rocket-packet-repairs/riscv/iris_empirical_load.inc',ROOT/'pipeline/fast_rocket_packets_checked.cpp'];report={'schema':'iris.empirical.Rocket_IBuf_coherence_replay_regression.v1','pass':True,'input_sha256':{str(x):sha(x)for x in inputs},'witness_sha256':sha(out/'witness.json'),'actual_typed_head_guard_preserved':True,'accepted_cache_actor_cancellation_policy_unchanged':True,'scope':'sameactualZephyrscalarELF/fixture; observed cold/coherence replay failure and explicit1M-instruction-cap progress control; fullOSexit and timingaccuracy remain separate gates','binary_sha256':run['binary_sha256'],'uart_sha256':run['uart_sha256'],'full_Zephyr_exit_verified':False};(out/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'pass':True,'report_sha256':sha(out/'report.json')}))
if __name__=='__main__':main()
